const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Function to mask clouds and shadows from Landsat 8/9 Collection 2
function maskL8L9clouds(image) {
  // Bits 3 (cloud) and 4 (cloud shadow) are set to 0.
  const qa = image.select('QA_PIXEL');
  const cloudShadowBitMask = 1 << 4;
  const cloudBitMask = 1 << 3;
  const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(cloudBitMask).eq(0));
  return image.updateMask(mask);
}

// Function to convert thermal band to Celsius
function applyScaleAndOffsetToCelsius(image) {
    const thermal = image.select('ST_B10');
    // Scale factor 0.00341802, offset 149.0 to get Kelvin, then subtract 273.15 for Celsius
    const tempC = thermal.multiply(0.00341802).add(149.0).subtract(273.15).rename('LST_C');
    return image.addBands(tempC);
}

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const phxAirport = ee.Geometry.Point([-112.0116, 33.4343]).buffer(1000); // Buffer to create a representative area
    const sierraEstrella = ee.Geometry.Rectangle([-112.35, 33.25, -112.20, 33.35]);
    const dateStart = '2023-07-19';
    const dateEnd = '2023-07-20'; // Use a 1-day range to catch the image

    // 2. Data Acquisition
    let collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
        .filterDate(dateStart, dateEnd)
        .filterBounds(sierraEstrella.union(phxAirport));

    let collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
        // Fallback to Landsat 8 if no Landsat 9 images are found
        collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
            .filterDate(dateStart, dateEnd)
            .filterBounds(sierraEstrella.union(phxAirport));
        collectionSize = collection.size().getInfo();
        if (collectionSize === 0) {
            console.log('No Landsat 8/9 images found for the specified date and location.');
            console.log('A: C1');
            return;
        }
    }

    // 3. Processing
    const image = ee.Image(collection.sort('CLOUD_COVER').first());
    const cloudCover = image.get('CLOUD_COVER').getInfo();
    const maskedImage = maskL8L9clouds(image);
    const tempImage = applyScaleAndOffsetToCelsius(maskedImage);
    const lstBand = tempImage.select('LST_C');

    // 4. Calculation
    const scale = 1000; // Use a coarse scale to avoid timeouts

    // Calculate stats for Sierra Estrella
    const estrellaStats = lstBand.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: sierraEstrella,
        scale: scale,
        maxPixels: 1e9
    });

    // Calculate stats for PHX Airport
    const airportStats = lstBand.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: phxAirport,
        scale: scale,
        maxPixels: 1e9
    });

    // Retrieve results asynchronously
    const estrellaResult = await ee.Number(estrellaStats.get('LST_C')).getInfo();
    const estrellaPixels = await ee.Number(estrellaStats.get('LST_C_count')).getInfo();
    const airportResult = await ee.Number(airportStats.get('LST_C')).getInfo();
    const airportPixels = await ee.Number(airportStats.get('LST_C_count')).getInfo();

    // 5. Validation & Final Answer
    console.log(`Image Cloud Cover: ${cloudCover.toFixed(2)}%`);
    console.log(`Sierra Estrella: Temp=${estrellaResult ? estrellaResult.toFixed(2) : 'N/A'} C, Pixels=${estrellaPixels}`);
    console.log(`PHX Airport: Temp=${airportResult ? airportResult.toFixed(2) : 'N/A'} C, Pixels=${airportPixels}`);

    if (estrellaPixels === 0 || airportPixels === 0) {
        console.log('No valid pixels remaining after cloud masking for one or both regions.');
        console.log('A: C2');
        return;
    }

    if (estrellaResult === null || airportResult === null) {
        console.log('Calculation failed; mean temperature is null.');
        console.log('A: C3');
        return;
    }

    if (estrellaResult > airportResult) {
        console.log('A: Yes');
    } else {
        console.log('A: No');
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  console.error(err);
  console.log('A: D');
});
